<script setup>
import { ref } from "vue";import FoodPicker from "./FoodPicker.vue";import{authFetch}from"../utils/auth.js";
const emit=defineEmits(["saved"]),text=ref(""),drafts=ref([]),parsing=ref(false),saving=ref(false),error=ref("");let batchRequestId="";const localDateTime=v=>{const d=v?new Date(v):new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};const kcal=i=>Math.round(((Number(i.protein)||0)*4+(Number(i.carbs)||0)*4+(Number(i.fat)||0)*9+(i.unit==="ml"?Number(i.quantity||0)*Number(i.alcohol_abv||0)/100*.789*7:0))*10)/10;
async function parse(){parsing.value=true;error.value="";try{const r=await authFetch("/api/ai/parse",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({text:text.value})});if(!r.ok)throw new Error((await r.json()).detail||"AI 解析失败");const data=await r.json();if(!data.items.length)throw new Error("未识别到可用的饮食信息");batchRequestId=crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;drafts.value=data.items.map(i=>({...i,eaten_at:localDateTime(i.eaten_at),matched:Boolean(i.food_id),add_to_library:!i.food_id,_food:null}))}catch(e){error.value=e.message}finally{parsing.value=false}}
function recalcMatched(i){if(!i._food)return;const ratio=Number(i.quantity||0)/i._food.base_amount;i.protein=+(i._food.protein*ratio).toFixed(2);i.fat=+(i._food.fat*ratio).toFixed(2);i.carbs=+(i._food.carbs*ratio).toFixed(2)}function match(i,f){Object.assign(i,{food_id:f.id,food_name:f.name,unit:f.unit,alcohol_abv:f.alcohol_abv||0,matched:true,nutrition_source:"food_library",add_to_library:false,_food:f});recalcMatched(i)}function unmatch(i){i.food_id=null;i.matched=false;i.nutrition_source="ai_estimated";i.add_to_library=true;i._food=null}
async function confirmAll(){error.value="";if(drafts.value.some(i=>!i.food_name||!Number(i.quantity))){error.value="请补全食物名称和数量";return}saving.value=true;try{const records=drafts.value.map(i=>({food_name:i.food_name,quantity:Number(i.quantity),unit:i.unit,food_id:i.food_id||null,protein:Number(i.protein||0),fat:Number(i.fat||0),carbs:Number(i.carbs||0),alcohol_abv:Number(i.alcohol_abv||0),nutrition_source:i.nutrition_source,add_to_library:i.add_to_library,meal_type:i.meal_type,eaten_at:i.eaten_at}));const r=await authFetch("/api/records/batch",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({records,request_id:batchRequestId})});if(!r.ok)throw new Error((await r.json()).detail||"保存草稿失败");const saved=await r.json();drafts.value=[];text.value="";batchRequestId="";emit("saved",saved)}catch(e){error.value=e.message}finally{saving.value=false}}
</script>
<template><section class="card ai-entry"><div class="section-heading"><div><p class="section-kicker">AI QUICK ENTRY</p><h2>自然语言录入</h2></div><span>解析后需确认才会保存</span></div><div class="ai-input"><textarea v-model.trim="text" rows="2" placeholder="例如：午饭吃了200g米饭、150g鸡胸肉和一个鸡蛋"></textarea><button class="primary" :disabled="parsing||!text" @click="parse">{{parsing?'解析中…':'AI 解析'}}</button></div><p v-if="error" class="error">{{error}}</p><div v-if="drafts.length" class="draft-list"><article v-for="(i,index) in drafts" :key="index" :class="{unmatched:!i.matched}"><header><strong>{{i.food_name}}</strong><span :class="['source-tag',i.nutrition_source]">{{i.nutrition_source==='food_library'?'食物库':'AI 估算'}}</span></header><FoodPicker :selected-id="i.food_id" placeholder="搜索并匹配食物库" @select="match(i,$event)" @clear="unmatch(i)"/><div class="draft-fields"><label>名称<input v-model="i.food_name"/></label><label>数量<input v-model.number="i.quantity" type="number" min="0" step="1"/></label><label>单位<select v-model="i.unit" :disabled="i.matched"><option>g</option><option>ml</option><option>个</option><option>份</option></select></label><label>卡路里（自动）<input :value="kcal(i)" disabled/></label><label v-if="i.unit==='ml'||i.alcohol_abv>0">酒精度 %<input v-model.number="i.alcohol_abv" type="number" min="0" max="100" step="1" :disabled="i.matched"/></label><label>碳水<input v-model.number="i.carbs" type="number" min="0" step="1" :disabled="i.matched"/></label><label>蛋白质<input v-model.number="i.protein" type="number" min="0" step="1" :disabled="i.matched"/></label><label>脂肪<input v-model.number="i.fat" type="number" min="0" step="1" :disabled="i.matched"/></label><label>餐次<select v-model="i.meal_type"><option>早餐</option><option>午餐</option><option>晚餐</option><option>加餐</option></select></label><label>时间<input v-model="i.eaten_at" type="datetime-local"/></label><label v-if="!i.matched" class="checkbox"><input v-model="i.add_to_library" type="checkbox"/>确认后加入食物库（保留估算标记）</label></div></article><button class="primary confirm-ai" :disabled="saving" @click="confirmAll">{{saving?'保存中…':'确认并写入记录'}}</button></div></section></template>
